import {
  index,
  integer,
  primaryKey,
  sqliteTable,
  text,
  uniqueIndex,
} from "drizzle-orm/sqlite-core"

// Better Auth tables (generated by the official CLI into ./auth-schema),
// re-exported here so drizzle-kit sees them.
import { account, session, user, verification } from "./auth-schema"

export { account, session, user, verification }

function timestamps() {
  return {
    createdAt: text()
      .notNull()
      .$defaultFn(() => new Date().toISOString()),
    updatedAt: text()
      .notNull()
      .$defaultFn(() => new Date().toISOString())
      .$onUpdate(() => new Date().toISOString()),
  }
}

function id() {
  return text()
    .primaryKey()
    .$defaultFn(() => crypto.randomUUID())
}

export const businesses = sqliteTable(
  "businesses",
  {
    id: id(),
    slug: text().notNull().unique(),
    name: text().notNull(),
    description: text(),
    phone: text(),
    address: text(),
    timezone: text().notNull(),
    currency: text().notNull(),
    googlePlaceId: text().unique(),
    category: text(),
    website: text(),
    status: text(),
    ownerId: text().references(() => user.id, { onDelete: "set null" }),
    detailsConfirmedAt: integer(),
    seats: integer().notNull().default(1),
    ...timestamps(),
  },
  (table) => [index("businesses_owner_idx").on(table.ownerId)]
)

export const businessHours = sqliteTable(
  "business_hours",
  {
    id: id(),
    businessId: text()
      .notNull()
      .references(() => businesses.id, { onDelete: "cascade" }),
    weekday: integer().notNull(),
    opensAt: text().notNull(),
    closesAt: text().notNull(),
    ...timestamps(),
  },
  (table) => [
    index("business_hours_business_idx").on(table.businessId, table.weekday),
  ]
)

export const services = sqliteTable(
  "services",
  {
    id: id(),
    businessId: text()
      .notNull()
      .references(() => businesses.id, { onDelete: "cascade" }),
    name: text().notNull(),
    description: text(),
    durationMinutes: integer().notNull(),
    priceMinor: integer(),
    photoUrl: text(),
    position: integer().notNull().default(0),
    ...timestamps(),
  },
  (table) => [
    index("services_business_idx").on(table.businessId, table.position),
  ]
)

export const teamMembers = sqliteTable(
  "team_members",
  {
    id: id(),
    businessId: text()
      .notNull()
      .references(() => businesses.id, { onDelete: "cascade" }),
    name: text().notNull(),
    photoUrl: text(),
    position: integer().notNull().default(0),
    ...timestamps(),
  },
  (table) => [
    index("team_members_business_idx").on(table.businessId, table.position),
  ]
)

export const businessPhotos = sqliteTable(
  "business_photos",
  {
    id: id(),
    businessId: text()
      .notNull()
      .references(() => businesses.id, { onDelete: "cascade" }),
    url: text().notNull(),
    position: integer().notNull().default(0),
    ...timestamps(),
  },
  (table) => [
    index("business_photos_business_idx").on(table.businessId, table.position),
  ]
)

export const addonGroups = sqliteTable(
  "addon_groups",
  {
    id: id(),
    businessId: text()
      .notNull()
      .references(() => businesses.id, { onDelete: "cascade" }),
    name: text().notNull(),
    prompt: text().notNull(),
    minSelect: integer().notNull().default(0),
    maxSelect: integer(),
    position: integer().notNull().default(0),
    ...timestamps(),
  },
  (table) => [
    index("addon_groups_business_idx").on(table.businessId, table.position),
  ]
)

export const addonOptions = sqliteTable(
  "addon_options",
  {
    id: id(),
    businessId: text()
      .notNull()
      .references(() => businesses.id, { onDelete: "cascade" }),
    groupId: text()
      .notNull()
      .references(() => addonGroups.id, { onDelete: "cascade" }),
    name: text().notNull(),
    description: text(),
    priceMinor: integer(),
    durationMinutes: integer().notNull().default(0),
    position: integer().notNull().default(0),
    ...timestamps(),
  },
  (table) => [
    index("addon_options_group_idx").on(table.groupId, table.position),
  ]
)

export const serviceAddonGroups = sqliteTable(
  "service_addon_groups",
  {
    businessId: text()
      .notNull()
      .references(() => businesses.id, { onDelete: "cascade" }),
    serviceId: text()
      .notNull()
      .references(() => services.id, { onDelete: "cascade" }),
    groupId: text()
      .notNull()
      .references(() => addonGroups.id, { onDelete: "cascade" }),
    position: integer().notNull().default(0),
    ...timestamps(),
  },
  (table) => [
    primaryKey({ columns: [table.serviceId, table.groupId] }),
    index("service_addon_groups_group_idx").on(table.groupId),
  ]
)

export const bookingAddons = sqliteTable(
  "booking_addons",
  {
    id: id(),
    businessId: text()
      .notNull()
      .references(() => businesses.id, { onDelete: "cascade" }),
    bookingId: text()
      .notNull()
      .references(() => bookings.id, { onDelete: "cascade" }),
    optionId: text().references(() => addonOptions.id, {
      onDelete: "set null",
    }),
    name: text().notNull(),
    priceMinor: integer(),
    durationMinutes: integer().notNull(),
    position: integer().notNull().default(0),
    ...timestamps(),
  },
  (table) => [index("booking_addons_booking_idx").on(table.bookingId)]
)

// From now on bookings.durationMinutes and bookings.priceMinor are the
// TOTALS (service + add-ons; priceMinor null only when the service has no
// price and no add-on has one). The add-ons are in booking_addons.
export const bookings = sqliteTable(
  "bookings",
  {
    id: id(),
    businessId: text()
      .notNull()
      .references(() => businesses.id, { onDelete: "cascade" }),
    serviceId: text().references(() => services.id, { onDelete: "set null" }),
    teamMemberId: text().references(() => teamMembers.id, {
      onDelete: "set null",
    }),
    serviceName: text().notNull(),
    teamMemberName: text(),
    durationMinutes: integer().notNull(),
    priceMinor: integer(),
    currency: text().notNull(),
    startAt: text().notNull(),
    endAt: text().notNull(),
    customerName: text().notNull(),
    customerPhone: text(),
    source: text().notNull().default("online"),
    note: text(),
    status: text().notNull().default("confirmed"),
    ...timestamps(),
  },
  (table) => [index("bookings_business_idx").on(table.businessId, table.startAt)]
)

// a service with NO rows here is done by everyone on the team; a service with rows is done only by those members.
export const teamMemberServices = sqliteTable(
  "team_member_services",
  {
    businessId: text()
      .notNull()
      .references(() => businesses.id, { onDelete: "cascade" }),
    teamMemberId: text()
      .notNull()
      .references(() => teamMembers.id, { onDelete: "cascade" }),
    serviceId: text()
      .notNull()
      .references(() => services.id, { onDelete: "cascade" }),
    ...timestamps(),
  },
  (table) => [
    primaryKey({ columns: [table.teamMemberId, table.serviceId] }),
    index("team_member_services_business_idx").on(table.businessId),
    index("team_member_services_service_idx").on(table.serviceId),
  ]
)

export const translations = sqliteTable(
  "translations",
  {
    id: id(),
    businessId: text()
      .notNull()
      .references(() => businesses.id, { onDelete: "cascade" }),
    entityId: text().notNull(),
    field: text().notNull(),
    language: text().notNull(),
    sourceText: text().notNull(),
    text: text().notNull(),
    ...timestamps(),
  },
  (table) => [
    uniqueIndex("translations_entity_field_language_idx").on(
      table.entityId,
      table.field,
      table.language
    ),
    index("translations_business_idx").on(table.businessId, table.language),
  ]
)

// One row per write the assistant runs (direct or confirmed), including
// failures. The summary is server-built, never model words.
export const assistantActions = sqliteTable(
  "assistant_actions",
  {
    id: id(),
    businessId: text()
      .notNull()
      .references(() => businesses.id, { onDelete: "cascade" }),
    ownerId: text().references(() => user.id, { onDelete: "set null" }),
    tool: text().notNull(),
    summary: text().notNull(),
    status: text().notNull(),
    ...timestamps(),
  },
  (table) => [index("assistant_actions_business_idx").on(table.businessId)]
)
